const DEFAULT_STARTUP_ID = "S0001";
function getCurrentStartupId() {
  const stored = sessionStorage.getItem("govinnovate_startup_id");
  // Migrate the legacy demo id used by earlier builds (S001 -> S0001).
  if (!stored || stored === "S001" || !/^S\d{4}$/.test(stored)) {
    sessionStorage.setItem("govinnovate_startup_id", DEFAULT_STARTUP_ID);
    return DEFAULT_STARTUP_ID;
  }
  return stored;
}

import { BarChart, Bar, XAxis, YAxis, Tooltip, ResponsiveContainer, PieChart, Pie, Cell, LineChart, Line, CartesianGrid, Legend } from "recharts";

const PURPLE = "#7c3aed";

class AppErrorBoundary extends React.Component {
  constructor(props){super(props);this.state={error:null};}
  static getDerivedStateFromError(error){return {error};}
  componentDidCatch(error,info){console.error("GOVINNOVATE UI error",error,info);}
  render(){
    if(this.state.error){
      return <div className="error-page"><div className="error-panel"><CircleAlert/><div><span className="eyebrow">UI ERROR RECOVERY</span><h2>This workspace could not be rendered</h2><p>{this.state.error?.message||"Unexpected frontend error."}</p><button className="primary-button small" onClick={()=>{sessionStorage.removeItem("govinnovate_role");location.reload();}}>Return to workspace selector</button></div></div></div>;
    }
    return this.props.children;
  }
}

function App() {
  const location = useLocation();
  const [role, setRole] = useState(sessionStorage.getItem("govinnovate_access_token") ? (sessionStorage.getItem("govinnovate_role") || "") : "");
  const [loginRole, setLoginRole] = useState(sessionStorage.getItem("govinnovate_login_role") || "");
  const [dark, setDark] = useState(localStorage.getItem("theme") === "dark");
  const [verified, setVerified] = useState(sessionStorage.getItem("startup_verified") === "yes");

  useEffect(() => {
    document.documentElement.dataset.theme = dark ? "dark" : "light";
    localStorage.setItem("theme", dark ? "dark" : "light");
  }, [dark]);
  useEffect(() => {
    if (sessionStorage.getItem("govinnovate_access_token")) {
      getCurrentUser().catch(() => {
        sessionStorage.removeItem("govinnovate_access_token");
        sessionStorage.removeItem("govinnovate_role");
        setRole("");
      });
    }
  }, []);

  if (location.pathname.startsWith("/passport/")) {
    return <Routes><Route path="/passport/:id" element={<PublicPassport />} /></Routes>;
  }

  const chooseRole = value => {
    sessionStorage.setItem("govinnovate_login_role", value);
    setLoginRole(value);
  };

  const completeLogin = data => {
    sessionStorage.setItem("govinnovate_access_token", data.access_token);
    sessionStorage.setItem("govinnovate_role", data.user.role);
    sessionStorage.setItem("govinnovate_login_role", data.user.role);
    if(data.user.role === "startup") sessionStorage.setItem("govinnovate_startup_id", data.user.user_id || DEFAULT_STARTUP_ID);
    setRole(data.user.role); setLoginRole(data.user.role);
    setVerified(sessionStorage.getItem("startup_verified") === "yes");
  };

  const logout = () => {
    sessionStorage.removeItem("govinnovate_access_token");
    sessionStorage.removeItem("govinnovate_role");
    sessionStorage.removeItem("govinnovate_login_role");
    sessionStorage.removeItem("startup_verified");
    setRole(""); setLoginRole(""); setVerified(false);
  };

  if (!role) return loginRole ? <WorkspaceLogin role={loginRole} dark={dark} setDark={setDark} onBack={() => {sessionStorage.removeItem("govinnovate_login_role");setLoginRole("")}} onSuccess={completeLogin} /> : <Landing dark={dark} setDark={setDark} chooseRole={chooseRole} />;
  if (role === "startup" && !verified) return <StartupVerification dark={dark} setDark={setDark} onDone={() => setVerified(true)} logout={logout} />;

  return <Shell role={role} dark={dark} setDark={setDark} logout={logout} />;
}

function WorkspaceLogin({ role, dark, setDark, onBack, onSuccess }) {
  const defaults={government:["government@govinnovate.local","gov123","Government Officer"],startup:["startup@govinnovate.local","startup123","Startup User"],expert:["expert@govinnovate.local","expert123","Expert Reviewer"]};
  const [email,setEmail]=useState(defaults[role]?.[0]||""); const [password,setPassword]=useState(defaults[role]?.[1]||""); const [busy,setBusy]=useState(false); const [error,setError]=useState("");
  const submit=async e=>{e.preventDefault();setBusy(true);setError("");try{const data=await login({email,password,role});onSuccess(data)}catch(err){setError(err.message||"Unable to sign in")}finally{setBusy(false)}};
  return <div className="auth-page"><header className="auth-nav"><Brand/><div><button className="icon-button" onClick={()=>setDark(!dark)}>{dark?<Sun/>:<Moon/>}</button><button className="ghost-button small" onClick={onBack}>Back</button></div></header><div className="auth-card"><div className="auth-symbol"><LockKeyhole/></div><span className="eyebrow">SECURE WORKSPACE LOGIN</span><h1>{role[0].toUpperCase()+role.slice(1)} access</h1><p>Demo authentication is enforced by the FastAPI backend. Your workspace permissions are attached to the signed session token.</p>{error&&<div className="inline-warning"><CircleAlert/><span>{error}</span></div>}<form className="auth-box" onSubmit={submit}><label>Email<input type="email" value={email} onChange={e=>setEmail(e.target.value)} required/></label><label>Password<input type="password" value={password} onChange={e=>setPassword(e.target.value)} required/></label><div className="demo-credentials"><b>Demo credentials</b><span>{defaults[role]?.[0]}</span><span>{defaults[role]?.[1]}</span></div><button className="primary-button" disabled={busy} type="submit">{busy?"Signing in…":"Sign in"}<ArrowUpRight/></button></form><small className="demo-note">Prototype authentication only. Credentials are local demo accounts; no external identity provider is connected.</small></div></div>;
}

